import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tabs=[t for (t,) in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")]
print("tables:", len(tabs))
print("--- icf-typed columns (P-G definition: name contains 'icf', not 'notes')")
import re
for t in tabs:
    for c in con.execute(f'pragma table_info("{t}")'):
        if re.search('icf', c[1]) and c[1]!='notes':
            fks=[(f[2],f[4]) for f in con.execute(f'pragma foreign_key_list("{t}")') if f[3]==c[1]]
            print(f"  {t}.{c[1]}  type={c[2]} notnull={c[3]}  fk={fks}")
print("--- FKs declared on the live lens/crossing tables")
for t in ['population_icf_links','access_need_icf','icf_medical_map','specifications','source_value_extractions','base_icf','access_needs','populations','base_taxonomy_identity']:
