        print(t, [(f[3],'->',f[2],f[4]) for f in con.execute(f'pragma foreign_key_list("{t}")')], "rows=", con.execute(f'select count(*) from "{t}"').fetchone()[0])
    except Exception as e: print(t, "ERR", e)
print("--- base_icf rows", con.execute("select count(*) from base_icf").fetchone())
print("--- access_needs DDL mention of situations:")
sql=con.execute("select sql from sqlite_master where name='access_needs'").fetchone()[0]
for line in sql.splitlines():
    if 'situation' in line: print("   ", line.strip())
print("--- indexes on slugs:", con.execute("select name, sql from sqlite_master where type='index' and tbl_name='slugs'").fetchall())
print("--- views naming slugs:", [n for (n,s) in con.execute("select name, sql from sqlite_master where type='view'") if re.search(r'\bslugs\b', s or '')])
